
// The host's framework identity. `host_registry!()` reads this constant, the
// generated `registrations()` table, and `XIRANG_NAMESPACE` (emitted by
// `host!()` above) from the crate root — all three are host wiring, not
// registration declarations: every registration face, module mount and identity
// assertion in this crate is generated by the build.
// 宿主的框架身份。`host_registry!()` 从 crate 根读这个常量、生成的 `registrations()`
// 表与 `XIRANG_NAMESPACE`（由上面的 `host!()` 发出）——三者都是宿主接线，不是注册声明：
// 本 crate 里每个注册面、模块挂载与身份断言都由构建生成。
pub const FRAMEWORK: FrameworkId = FrameworkId::new("xirang.island-loop");

/// Assemble this host's registry from the build's generated registration table.
/// 由构建生成的注册表装配本宿主的注册机。
pub fn base_registry() -> Registry {
    xirang_toolchain::host_registry!().expect("this host's faces register")
}
